use jsonwebtoken::jwk::Jwk;
use jsonwebtoken::{Algorithm, EncodingKey, Header, encode};
use mandate_federation::authenticate::{
    AuthenticateFederation, Authenticated, authenticate_federation,
};
use mandate_federation::record::{
    ConnectionState, FederationConnection, FederationEvent, Projection,
};
use mandate_federation::verifier_real::{
    AllowedAlgorithms, FixedClock, InMemoryJwks, JwksSource, RealVerifier, RefusalReason, UreqJwks,
};
use mandate_federation::{
    DenialClause, Denied, FederationVerifier, RecordingSessionIssuer, RequestContext,
};
