/// No input this file can build makes the verifier panic or return an empty proof.
#[test]
fn nothing_malformed_panics_or_verifies() {
    let rsa = keys(Algorithm::RS256, "one-2026-09");
    let source = InMemoryJwks::new();
    source.publish(&Issuer::new(ISSUER_ONE), key_set(&[&rsa]));
    let clock = FixedClock::at(NOW);
    let verifier = verifier(&source, &clock, &[(connection(1), RS256)]);
    let header = serde_json::json!({ "alg": "RS256", "typ": "JWT", "kid": rsa.kid });

    let mut malformed: Vec<(String, CredentialProof)> = vec![
        ("empty".to_owned(), CredentialProof::from_bytes(Vec::new())),
        (
            "two dots".to_owned(),
            CredentialProof::from_bytes(b"..".to_vec()),
        ),
        (
            "four segments".to_owned(),
            CredentialProof::from_bytes(b"a.b.c.d".to_vec()),
        ),
        (
            "not utf-8".to_owned(),
            CredentialProof::from_bytes(vec![0xff, 0xfe, 0x2e, 0x00, 0x2e]),
        ),
        (
            "header not base64url".to_owned(),
            CredentialProof::from_bytes(b"!!!!.e30.c2ln".to_vec()),
        ),
        (
            "header padded".to_owned(),
            CredentialProof::from_bytes(format!("{}==.e30.c2ln", base64url(b"{}")).into_bytes()),
        ),
        (
            "header is a list".to_owned(),
            CredentialProof::from_bytes(
                format!("{}.e30.c2ln", base64url(b"[\"RS256\"]")).into_bytes(),
            ),
        ),
        (
            "alg is a number".to_owned(),
            CredentialProof::from_bytes(
                format!("{}.e30.c2ln", base64url(br#"{"alg":256}"#)).into_bytes(),
            ),
        ),
        (
            "empty payload".to_owned(),
            CredentialProof::from_bytes(
                format!("{}..c2ln", base64url(header.to_string().as_bytes())).into_bytes(),
            ),
        ),
        (
            "payload is a list".to_owned(),
            minted_under(&rsa, &header, &serde_json::json!([1, 2, 3])),
        ),
        (
            "payload is a string".to_owned(),
            minted_under(&rsa, &header, &serde_json::json!("claims")),
        ),
        (
            "claims are deeply nested".to_owned(),
            minted_under(&rsa, &header, &nested(400)),
        ),
        (
            "a very long kid".to_owned(),
            minted_under(
                &rsa,
                &serde_json::json!({ "alg": "RS256", "kid": "k".repeat(200_000) }),
                &claims(ISSUER_ONE, SUBJECT),
            ),
        ),
        (
            "a very long subject".to_owned(),
            mint(
                &rsa,
                &with(
                    claims(ISSUER_ONE, SUBJECT),
                    "sub",
                    "s".repeat(1_000_000).into(),
                ),
            ),
        ),
        (
            "an expiry at the end of time".to_owned(),
            mint(
                &rsa,
                &with(claims(ISSUER_ONE, SUBJECT), "exp", u64::MAX.into()),
            ),
        ),
        (
            "a not-before at the end of time".to_owned(),
            mint(
                &rsa,
                &with(claims(ISSUER_ONE, SUBJECT), "nbf", u64::MAX.into()),
            ),
        ),
    ];
    malformed.push((
        "a signature that is not base64url".to_owned(),
        CredentialProof::from_bytes(
            format!(
                "{}.{}.!!!",
                base64url(header.to_string().as_bytes()),
                base64url(claims(ISSUER_ONE, SUBJECT).to_string().as_bytes())
            )
            .into_bytes(),
        ),
    ));

    for (name, proof) in malformed {
        let outcome = std::panic::catch_unwind(AssertUnwindSafe(|| {
            verifier.verify(&a_connection(ISSUER_ONE), &proof)
        }));
        match outcome {
            Err(_) => panic!("`{name}` panicked the verifier"),
            // The value is summarized rather than printed: one of these inputs is a
            // megabyte long, and a megabyte of assertion output buries every other
            // result in the run.
            Ok(Ok(verified)) => panic!(
                "`{name}` verified: a subject of {} bytes beginning {:?}",
                verified.subject().as_str().len(),
                verified
                    .subject()
                    .as_str()
                    .chars()
                    .take(24)
                    .collect::<String>()
            ),
            Ok(Err(denied)) => assert_ne!(
                denied.reason,
                DenialReason::Denied,
                "`{name}` denied without naming an invalid credential"
            ),
        }
    }
}

fn nested(depth: usize) -> serde_json::Value {
    let mut value = serde_json::json!(1);
    for _ in 0..depth {
        value = serde_json::Value::Array(vec![value]);
    }
    serde_json::json!({ "iss": ISSUER_ONE, "sub": SUBJECT, "aud": CLIENT, "exp": NOW + 300, "deep": value })
}

/// An access token of the type RFC 9068 declares is refused, whatever else it carries.
#[test]
fn an_rfc_9068_access_token_type_is_refused() {
    let rsa = keys(Algorithm::RS256, "one-2026-09");
    let source = InMemoryJwks::new();
    source.publish(&Issuer::new(ISSUER_ONE), key_set(&[&rsa]));
    let clock = FixedClock::at(NOW);
    let verifier = verifier(&source, &clock, &[(connection(1), RS256)]);
    let header = serde_json::json!({ "alg": "RS256", "typ": "at+jwt", "kid": rsa.kid });

    let denied = verifier
        .verify(
            &a_connection(ISSUER_ONE),
            &minted_under(&rsa, &header, &claims(ISSUER_ONE, SUBJECT)),
        )
        .expect_err("the verifier admits one token type");

    assert_eq!(
        verifier.refusals(),
        vec![RefusalReason::UnexpectedTokenType],
        "recorded so that the deployment can see why every login failed"
    );
    assert_eq!(denied.clause, DenialClause::ProofInvalid);
}
